Add-Type -AssemblyName System.Drawing
$ErrorActionPreference='Stop';$root=Split-Path -Parent $MyInvocation.MyCommand.Path;$W=1080;$H=1350
$paper=[Drawing.ColorTranslator]::FromHtml('#FBFAF7');$white=[Drawing.Color]::White;$navy=[Drawing.ColorTranslator]::FromHtml('#0D326F');$teal=[Drawing.ColorTranslator]::FromHtml('#087E78');$ink=[Drawing.ColorTranslator]::FromHtml('#17233D');$muted=[Drawing.ColorTranslator]::FromHtml('#596173');$gold=[Drawing.ColorTranslator]::FromHtml('#A87816');$line=[Drawing.ColorTranslator]::FromHtml('#DED8CB');$soft=[Drawing.ColorTranslator]::FromHtml('#F2F6FB');$warn=[Drawing.ColorTranslator]::FromHtml('#FFF1CF')
function F($n,$b=$false){New-Object Drawing.Font('Malgun Gothic',$n,($(if($b){[Drawing.FontStyle]::Bold}else{[Drawing.FontStyle]::Regular})),[Drawing.GraphicsUnit]::Pixel)}
function RR($g,$brush,$pen,$x,$y,$w,$h,$r){$p=New-Object Drawing.Drawing2D.GraphicsPath;$p.AddArc($x,$y,$r,$r,180,90);$p.AddArc($x+$w-$r,$y,$r,$r,270,90);$p.AddArc($x+$w-$r,$y+$h-$r,$r,$r,0,90);$p.AddArc($x,$y+$h-$r,$r,$r,90,90);$p.CloseFigure();if($brush){$g.FillPath($brush,$p)};if($pen){$g.DrawPath($pen,$p)};$p.Dispose()}
function T($g,$s,$font,$color,$x,$y,$w,$h){$b=New-Object Drawing.SolidBrush($color);$g.DrawString($s,$font,$b,[Drawing.RectangleF]::new($x,$y,$w,$h));$b.Dispose()}
function BeginCard($n,$kicker,$title){$b=New-Object Drawing.Bitmap($W,$H);$g=[Drawing.Graphics]::FromImage($b);$g.SmoothingMode='HighQuality';$g.TextRenderingHint='ClearTypeGridFit';$g.Clear($paper);T $g '보험워크 · 실손 재가입 안내' (F 24 $true) $gold 64 52 700 42;RR $g (New-Object Drawing.SolidBrush($navy)) $null 948 46 66 66 22;T $g $n (F 29 $true) $white 968 58 40 42;T $g $kicker (F 31 $true) $teal 64 145 900 48;T $g $title (F 60 $true) $ink 64 205 940 155;@($b,$g)}
function Box($g,$x,$y,$w,$h,$color=$white){RR $g (New-Object Drawing.SolidBrush($color)) (New-Object Drawing.Pen($line,2)) $x $y $w $h 24}
function Save($b,$g,$name){$b.Save((Join-Path $root $name),[Drawing.Imaging.ImageFormat]::Png);$g.Dispose();$b.Dispose()}
$a=BeginCard '1' '내 실손의 가입 시기를 확인하세요' "내 실손,`n언제 재가입할까요?";$b=$a[0];$g=$a[1];Box $g 64 405 952 270 $soft;T $g '2013.04 ~ 2021.06 가입' (F 34 $true) $navy 104 440 800 48;T $g '재가입 주기  15년' (F 42 $true) $teal 104 505 800 58;T $g '예) 2013.04.01 가입 → 2028.04.01 재가입' (F 30) $ink 104 590 850 48;Box $g 64 705 952 270 $soft;T $g '2021.07 ~ 2026.05 초 가입' (F 34 $true) $navy 104 740 850 48;T $g '재가입 주기  5년' (F 42 $true) $teal 104 805 800 58;T $g '예) 2021.07.01 가입 → 2026.07.01 재가입' (F 30) $ink 104 890 850 48;Box $g 64 1010 952 220 $warn;T $g '꼭 확인하세요' (F 32 $true) $gold 104 1040 500 45;T $g "가입일만 보지 말고 보험증권의 재가입 조항과`n실제 재가입 예정일을 함께 확인하세요." (F 31) $ink 104 1092 850 92;T $g '※ 2013년 3월 이전 계약 중에는 재가입 조건이 없는 계약도 있습니다.' (F 21) $muted 72 1275 930 34;Save $b $g 'customer-card-01.png'
$a=BeginCard '2' '안내가 오면 순서대로 확인하세요' "실손 재가입은`n이렇게 진행돼요";$b=$a[0];$g=$a[1];$steps=@(@('1','만기 전 안내 확인','보험사의 문자·우편·앱 안내를 확인하세요.'),@('2','변경 내용 확인','보장·자기부담금·보험료를 비교하세요.'),@('3','재가입 의사 선택','안내된 방법과 기한에 맞춰 응답하세요.'),@('4','처리 결과 확인','새 보험증권과 재가입 완료 여부를 확인하세요.'));$y=410;foreach($s in $steps){Box $g 64 $y 952 160;RR $g (New-Object Drawing.SolidBrush($navy)) $null 100 ($y+42) 68 68 20;T $g $s[0] (F 30 $true) $white 121 ($y+52) 40 42;T $g $s[1] (F 34 $true) $navy 205 ($y+24) 760 48;T $g $s[2] (F 30) $muted 205 ($y+78) 760 48;$y+=180};Box $g 64 1150 952 120 $warn;T $g '주소나 휴대전화가 바뀌었다면 보험사에 미리 등록하세요.' (F 31 $true) $gold 98 1182 880 55;Save $b $g 'customer-card-02.png'
$a=BeginCard '3' '제때 재가입하지 않으면?' "세대별 결과가`n다를 수 있어요";$b=$a[0];$g=$a[1];Box $g 64 405 952 220 $soft;T $g '2·3세대' (F 38 $true) $navy 104 440 300 55;T $g "별도 보호장치가 없는 계약은`n재가입을 놓치면 보장이 종료될 수 있습니다." (F 31) $ink 104 505 850 92;Box $g 64 655 952 220 ([Drawing.ColorTranslator]::FromHtml('#F4EEFA'));T $g '4세대' (F 38 $true) ([Drawing.ColorTranslator]::FromHtml('#65328F')) 104 690 300 55;T $g "보호장치에 따라 우선 자동연장된 뒤`n연락이 닿으면 재가입 절차를 진행합니다." (F 31) $ink 104 755 850 92;Box $g 64 905 952 240 $warn;T $g '5세대' (F 38 $true) $gold 104 940 300 55;T $g "일정 기간 우선 연장될 수 있지만`n기한 안에 재가입하지 않으면 종료될 수 있습니다." (F 31) $ink 104 1005 850 92;RR $g (New-Object Drawing.SolidBrush($navy)) $null 64 1180 952 110 24;T $g '세대명만 믿지 말고 내 보험증권과 약관을 확인하세요.' (F 29 $true) $white 100 1208 870 55;Save $b $g 'customer-card-03.png'
$a=BeginCard '4' '자동연장 후에도 확인이 필요합니다' "연장됐다고`n끝난 게 아니에요";$b=$a[0];$g=$a[1];Box $g 64 405 952 195 $soft;T $g '보험금 청구 또는 연락이 닿으면' (F 34 $true) $navy 104 440 820 48;T $g '보험사에서 실제 재가입 절차를 진행할 수 있습니다.' (F 31) $ink 104 505 850 48;Box $g 64 630 952 250 $warn;T $g '자동연장 뒤 철회·환급' (F 34 $true) $gold 104 665 780 48;T $g "약관에서 정한 기간 안에는 취소·환급이 가능한지,`n기간이 지나면 환급액이 어떻게 달라지는지 확인하세요." (F 31) $ink 104 730 850 100;Box $g 64 910 952 180 $soft;T $g '연락처를 꼭 최신으로' (F 34 $true) $navy 104 945 720 48;T $g '주소와 휴대전화를 보험사에 미리 등록하세요.' (F 31) $ink 104 1010 820 48;RR $g (New-Object Drawing.SolidBrush($navy)) $null 64 1120 952 145 24;T $g "핵심 정리`n자동연장은 임시 보호일 수 있습니다. 정상 재가입 여부를 꼭 확인하세요." (F 30 $true) $white 100 1145 870 95;T $g '※ 실제 처리 기준은 해당 계약의 약관과 보험사 안내문을 우선합니다.' (F 21) $muted 72 1290 920 30;Save $b $g 'advisor-checklist.png'
